\label{thm:inherited-eigenspace}
  Let \(\lambda\in\sigma(L_G)\), let \(m=m_\lambda(L_G)\), and let
\(Q_\lambda\in\mathbb R^{n\times m}\) have orthonormal columns spanning
\(E_\lambda(L_G)\). Then the following equalities hold:
\begin{equation}
\label{eq:inherited-space-characterizations}
\mathcal U_\lambda
=
\ker(T_{\lambda,\Omega})
=
E_\lambda(L_G)\cap\ker(B^T)
=
\{Q_\lambda a:a\in\ker(B^TQ_\lambda)\}.
\end{equation}
In particular, the following are equivalent:
\begin{enumerate}
\item[(i)] $\mathcal{U}_{\lambda} \neq \{0\}$, that is, $\lambda$  is preserved through inheritance;
\item[(ii)] $B^TQ_{\lambda}$ does not have full column rank;
\item[(iii)] $Q_{\lambda}^TB\Omega B^T Q_{\lambda}$ is singular. 
\end{enumerate}

\label{cor:inherited-dimension}
Let \(\lambda\in\sigma(L_G)\), let \(m=m_\lambda(L_G)\), and let
\(Q_\lambda\in\mathbb R^{n\times m}\) have orthonormal columns spanning
\(E_\lambda(L_G)\). Then
\begin{equation}
\label{eq:inherited-dimension}
\dim\mathcal U_\lambda
=
m_\lambda(L_G)-\operatorname{rank}(B^TQ_\lambda).
\end{equation}
In particular, if the number $p$ of updated edges is smaller than \(m_\lambda(L_G)\),  then \(\lambda\) is necessarily
preserved through inheritance.

\label{lem:fibers-orthogonal-representatives} Let \(y_1,y_2\in E_\lambda(L_{G+H})\). Then \begin{equation} \label{eq:same-edge-difference-fiber} T_{\lambda,\Omega}(y_1)=T_{\lambda,\Omega}(y_2) \quad\text{if and only if}\quad y_1-y_2\in\mathcal U_\lambda. \end{equation} 
Consequently, if \(y\in E_\lambda(L_{G+H})\) and \(w=T_{\lambda,\Omega}(y)\), then
\begin{equation} 
\label{eq:same-edge-difference-set} 
\left\{z\in E_\lambda(L_{G+H}): T_{\lambda,\Omega}(z)=w\right\} = y+\mathcal U_\lambda. 
\end{equation}
Moreover, this set contains a unique vector in $\mathcal{C}_{\lambda, \Omega}.$

The equivalence in \eqref{eq:same-edge-difference-fiber} follows immediately from $\ker(T_{\lambda,\Omega})=\mathcal U_\lambda$. Then, 
\eqref{eq:same-edge-difference-set} immediately follows from \eqref{eq:same-edge-difference-fiber}.

It remains to prove the last statement.
Let $z\in(y+\mathcal{U}_{\lambda
}).$ Write $z=z_{1}+z_{2}$ with $z_{1}\in\mathcal{U}_{\lambda}$ and $z_{2}\in\mathcal{C}_{\lambda,\Omega}.$ Then, $T_{\lambda,\Omega}(z_{2})=T_{\lambda,\Omega}(z)=w.$ So, $z_{2}\in(y+\mathcal{U}_{\lambda})\cap\mathcal{C}_{\lambda,\Omega}$.

To prove uniqueness, suppose that $z^{\prime}\in(y+\mathcal{U}_{\lambda})\cap\mathcal{C}_{\lambda,\Omega}$. Then $T_{\lambda,\Omega}(z^{\prime
})=T_{\lambda,\Omega}(z_{2}),$ implying that $z^{\prime}-z_{2}\in
\mathcal{U}_{\lambda}$ by \eqref{eq:same-edge-difference-fiber}. Since $z^{\prime}-z_{2}\in\mathcal{C}_{\lambda,\Omega
}\subseteq \mathcal{U}_{\lambda}^{\perp},$ it follows that $z^{\prime}=z_{2}.$

\label{thm:updated-eigenspace-decomposition}
Let \(\lambda\in\sigma(L_G)\). Then
\begin{equation}
\label{eq:inherited-emergent-decomposition}
E_\lambda(L_{G+H})
=
\mathcal U_\lambda
\mathbin{\oplus^\perp}
\Phi_{\lambda,\Omega}
\bigl(\mathcal S_{\lambda,\Omega}\bigr).
\end{equation}

\label{cor:weighted-algebraic-multiplicity}
With the notation above,
\begin{equation}
\label{eq:weighted-algebraic-multiplicity}
m_\lambda(L_{G+H})
=
m_\lambda(L_G)
-\operatorname{rank}(B^TQ_\lambda)
+\dim \ker F_\lambda(\Omega).
\end{equation}
In particular, emergence occurs if and only if
\(\ker F_\lambda(\Omega)\neq\{0\}\).

\label{thm:explicit-reconstruction}
With the notation above,
\begin{equation}
\label{eq:canonical-emergent-reconstruction}
\mathcal C_{\lambda,\Omega}
=
\left\{
y_c:c\in\ker F_\lambda(\Omega)
\right\}.
\end{equation}

\label{cor:basis-updated-eigenspace}
Let \(\{h_1,\ldots,h_s\}\) be a basis of
\(\ker(B^TQ_\lambda)\), and let \(\{c_1,\ldots,c_r\}\) be a basis of
\(\ker F_\lambda(\Omega)\). Then
\begin{equation}\label{eq:basis}
\{Q_\lambda h_1,\ldots,Q_\lambda h_s\}\cup\{
y_{c_1},\ldots,y_{c_r}\}
\end{equation}
is a basis of \(E_\lambda(L_{G+H})\), in which the first subset is a
basis of $\mathcal{U}_{\lambda}$ and the second is  a
basis of $\mathcal{C}_{\lambda, \Omega}$.
